/// <reference path="../manga-provider.d.ts" />
/// <reference path="../../core.d.ts" />

class Provider implements MangaProvider {
    private url: string = "https://mangafire.to"

    private async fetch(url: string, options: RequestInit = {}): Promise<Response> {
        const defaultHeaders = {
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/151.0.0.0 Safari/537.36",
            "Accept": "application/json, text/plain, */*",
        }

        const mergedOptions: RequestInit = {
            ...options,
            headers: {
                ...defaultHeaders,
                ...options.headers,
            },
        }

        return fetch(url, mergedOptions)
    }

    private getMangaId(url: string): string {
        let value = String(url || "")
        value = value.split("?")[0]
        value = value.replace(/\/+$/, "")

        if (value.indexOf("/title/") >= 0) {
            const last = value.substring(value.lastIndexOf("/") + 1)
            return last.split("-")[0]
        }

        if (value.indexOf("/manga/") >= 0) {
            const last = value.substring(value.lastIndexOf("/") + 1)
            const dot = last.lastIndexOf(".")
            if (dot >= 0) {
                return last.substring(dot + 1)
            }
        }

        return ""
    }

    async search({ query }: QueryOptions): Promise<SearchResult[]> {
        const searchUrl = `${this.url}/api/titles?keyword=${encodeURIComponent(query)}&language=en&limit=30&page=1`

        const response = await this.fetch(searchUrl, {
            method: "GET",
            headers: {
                "Referer": `${this.url}/`,
            },
        })

        const data = await response.json() as any
        const items = data && Array.isArray(data.items) ? data.items : []

        const searchResults: SearchResult[] = []

        for (let i = 0; i < items.length; i++) {
            const item = items[i]

            if (!item || !item.url || !item.title) {
                continue
            }

            const id = this.getMangaId(String(item.url))

            if (!id) {
                continue
            }

            const result: SearchResult = {
                id: id,
                title: String(item.title),
                synonyms: [],
                year: 0,
            }

            if (item.poster && item.poster.medium) {
                result.image = String(item.poster.medium)
            }

            searchResults.push(result)
        }

        return searchResults
    }

    async findChapters(mangaId: string): Promise<ChapterDetails[]> {
        const id = this.getMangaId(mangaId) || mangaId

        const chapterUrl = `${this.url}/api/titles/${encodeURIComponent(id)}/chapters`

        const chapters: ChapterDetails[] = []
        const seen: { [key: string]: boolean } = {}

        const limit = 200
        let page = 1
        let hasNext = true

        while (hasNext && page <= 100) {
            const url =
                `${chapterUrl}?language=en&sort=number&order=desc&limit=${limit}&page=${page}`

            const response = await this.fetch(url, {
                method: "GET",
                headers: {
                    "Referer": `${this.url}/title/${encodeURIComponent(id)}`,
                },
            })

            const data = await response.json() as any
            const items = data && Array.isArray(data.items) ? data.items : []

            for (let i = 0; i < items.length; i++) {
                const item = items[i]

                if (!item || item.id === undefined || item.id === null) {
                    continue
                }

                const chapterId = String(item.id)

                if (seen[chapterId]) {
                    continue
                }

                seen[chapterId] = true

                let chapterNumber = ""
                if (item.number !== undefined && item.number !== null) {
                    chapterNumber = String(item.number)
                }

                let title = "Chapter"
                if (chapterNumber !== "") {
                    title = `Ch. ${chapterNumber}`
                }

                if (item.name) {
                    title = `${title}: ${String(item.name)}`
                }

                chapters.push({
                    id: chapterId,
                    url: `${this.url}/title/${encodeURIComponent(id)}/${encodeURIComponent(chapterId)}`,
                    title: title,
                    chapter: chapterNumber,
                    index: 0,
                })
            }

            hasNext = !!(data && data.meta && data.meta.hasNext === true)
            page++
        }

        chapters.reverse()

        for (let i = 0; i < chapters.length; i++) {
            chapters[i].index = i
        }

        return chapters
    }

    async findChapterPages(chapterId: string): Promise<ChapterPage[]> {
        const chapterUrl = `${this.url}/api/chapters/${encodeURIComponent(chapterId)}`

        const response = await this.fetch(chapterUrl, {
            method: "GET",
            headers: {
                "Referer": `${this.url}/`,
            },
        })

        const data = await response.json() as any
        const sourcePages =
            data &&
            data.data &&
            Array.isArray(data.data.pages)
                ? data.data.pages
                : []

        const pages: ChapterPage[] = []

        for (let i = 0; i < sourcePages.length; i++) {
            const item = sourcePages[i]

            if (!item || !item.url) {
                continue
            }

            pages.push({
                url: String(item.url),
                index: pages.length,
                headers: {
                    "Referer": this.url,
                },
            })
        }

        return pages
    }

    getSettings(): Settings {
        return {
            supportsMultiLanguage: false,
            supportsMultiScanlator: false,
        }
    }
}
